<template>
  <template v-for="chart in charts" :key="chart.id">
    <div v-if="isBreakDashboardElement(chart)" class="col-span-12" />
    <!-- A section label carries no data, so it gets no card: a bordered panel around one line of text
         reads as a chart that failed to load. -->
    <h2 v-else-if="isSectionDashboardElement(chart)" class="col-span-12 mt-2 text-xl font-semibold tracking-tight">
      {{ chart.title }}
    </h2>
    <DashboardTabGroup
      v-else-if="isTabGroupDashboardElement(chart)"
      class="col-span-12"
      :chart="chart"
      :project-id="projectId"
      :dashboard-id="dashboardId"
      :params="params"
      :map-date-range="mapDateRange"
      :query-key="queryKey"
      :map-type="mapType"
    />
    <Card
      v-else
      :class="{
        'col-span-12': chart.cols === 12,
        'col-span-12 lg:col-span-9': chart.cols === 9,
        'col-span-12 lg:col-span-6': chart.cols === 6,
        'col-span-12 sm:col-span-6 lg:col-span-4': chart.cols === 4,
        'col-span-12 sm:col-span-6 lg:col-span-3': chart.cols === 3,
      }"
    >
      <CardHeader
        v-if="!isMdDashboardElement(chart) && chart.title"
        class="flex !flex-row items-center justify-between flex-wrap"
      >
        <div class="flex flex-col gap-1 w-full">
          <div class="flex flex-row items-center justify-between gap-1">
            <CardTitle>
              {{ chart.title }}
            </CardTitle>

            <Popover v-if="chart.popover_description">
              <PopoverTrigger><CircleQuestionMarkIcon class="w-5 h-5" /></PopoverTrigger>
              <PopoverContent side="top" class="text-wrap max-w-72 w-fit p-4 z-40">
                {{ chart.popover_description }}
              </PopoverContent>
            </Popover>
          </div>
          <CardDescription v-if="chart.description">
            <p class="text-sm text-muted-foreground">{{ chart.description }}</p>
          </CardDescription>
        </div>
        <Button
          v-if="isChartDashboardElement(chart) && chart.toggle_fill && chart.datasets"
          variant="outline"
          size="sm"
          @click="toggleFill(chart)"
          >Fill: <span class="capitalize">{{ chart.datasets[0].fill ? chart.datasets[0].fill : 'None' }}</span></Button
        >
      </CardHeader>
      <CardContent>
        <!-- Markdown notes are the only dashboard element that links out, and an unstyled anchor is
             indistinguishable from the text around it. Scoped here rather than on AppMarkdown, which
             also renders user-written notes elsewhere in the app. -->
        <AppMarkdown
          v-if="chart.type === 'md' && chart.content"
          :markdown="chart.content"
          class="[&_a:hover]:text-primary [&_a]:underline [&_a]:underline-offset-4"
        />
        <InfoValueChart v-if="chart.type === 'info-value'" :chart="chart" />
        <ComplexInfoValueChart v-if="chart.type === 'complex-info-value'" :chart="chart" />
        <GraphChart v-if="isChartDashboardElement(chart)" :chart="chart" />
        <BarBreakdownChart v-if="isBarListDashboardElement(chart)" :chart="chart" />
        <TableChart v-if="isTableDashboardElement(chart)" :chart="chart" />
        <HexagonMapCharts
          v-if="isMapDashboardElement(chart)"
          :init-view="chart.initial_view"
          :dashboard-id="dashboardId"
          :project-id="projectId"
          :question-hash="chart.map_id"
          :date-range="mapDateRange"
          :type="mapType"
          :canvassers-ids="params?.canvasser_ids"
          :regions="params?.regions"
          :timezone="params?.timezone"
        />
        <CalendarChart
          v-if="isCalendarDashboardElement(chart)"
          :chart="chart"
          :available-dates="processDateRangeValue({ start: props.params.start_date, end: props.params.end_date })"
        />
      </CardContent>
    </Card>
  </template>
</template>

<script setup lang="ts">
import type { DashboardGraph, DashboardChartResponse, GetCanvassingProjectResponsesDashboardData } from '~/client';
import { CircleQuestionMarkIcon } from 'lucide-vue-next';
import type { mapTypes } from '~/types/dashboards/mapTypes';

interface Props {
  charts: DashboardChartResponse['charts'];
  projectId?: string;
  dashboardId?: string;
  params: GetCanvassingProjectResponsesDashboardData['query'];
  mapDateRange?: { startDate: string; endDate: string } | null;
  queryKey: any[];
  mapType: mapTypes | null;
}

const props = withDefaults(defineProps<Props>(), {
  projectId: undefined,
  dashboardId: undefined,
  mapDateRange: null,
});

function toggleFill(chart: DashboardGraph) {
  if (!chart.datasets || chart.datasets.length === 0) return;
  const currentFill = chart.datasets[0].fill;
  const newFill = currentFill === 'stack' ? false : 'stack';

  const queryCache = useQueryCache();
  queryCache.setQueryData(props.queryKey, (oldData: any) => {
    if (!oldData) return oldData;
    const updatedCharts = oldData.charts.map((c: DashboardElements) => {
      if (c.id === chart.id && isChartDashboardElement(c) && c.datasets && c.datasets.length > 0) {
        const updatedDatasets = c.datasets.map((dataset) => ({
          ...dataset,
          fill: newFill,
        }));
        return { ...c, datasets: updatedDatasets };
      }
      return c;
    });
    return { ...oldData, charts: updatedCharts };
  });
}
</script>
