<template>
  <HexagonMapChart
    v-model:map-bounds="mapBounds"
    v-model:zoom="zoom"
    :data="data"
    :refetch="refetch"
    :init-view="initView"
  />
</template>

<script setup lang="ts">
import type { MapView } from '~/client';
import { getPublicQuestionDashboardMap } from '~/client';
import type { BoundsCorners } from '~/types/dashboards/mapTypes';

interface Props {
  initView: MapView;
  questionHash: string;
  dashboardId: string;
  dateRange: { startDate: string; endDate: string };
  regions?: string[] | null;
  timezone?: string | null;
}

const props = withDefaults(defineProps<Props>(), { regions: () => [], timezone: null });

const zoom = ref<number>(5);
const mapBounds = ref<BoundsCorners | null>(null);

const { data, refetch } = useQuery({
  key: () => [
    'share.projects.dashboard.id.map',
    props.dashboardId,
    props.questionHash,
    props.dateRange.startDate,
    props.dateRange.endDate,
    props.regions,
  ],
  query: () =>
    getPublicQuestionDashboardMap({
      composable: '$fetch',
      path: { public_hash: props.dashboardId, question_hash: props.questionHash },
      body: {
        from_date: props.dateRange.startDate,
        to_date: props.dateRange.endDate,
        scale: zoom.value,
        regions: props.regions && props.regions.length ? props.regions : undefined,
        ...(props.timezone ? { timezone: props.timezone } : {}),
        ...(mapBounds.value
          ? {
              left_top_corner: mapBounds.value.top_left,
              right_bottom_corner: mapBounds.value.bottom_right,
            }
          : {}),
      } as any,
    }),
  enabled: () => !!mapBounds.value,
});
</script>
