<template>
  <ResponsiveTable class="max-h-[450px] overflow-auto">
    <ResponsiveTableHeader class="sticky top-0 z-10">
      <ResponsiveTableHead
        v-for="head in chart.data.header"
        :key="head.label"
        :class="cn(alignments(head.alignment), textWrap(head.nowrap), 'whitespace-pre')"
      >
        {{ head.label }}
      </ResponsiveTableHead>
    </ResponsiveTableHeader>
    <ResponsiveTableBody>
      <ResponsiveTableEmpty
        v-if="!chart.data.rows || chart.data.rows.length === 0"
        :cols="4"
        :cols-sm="4"
        :colspan="chart.data.header.length"
      >
        No data for selected period
      </ResponsiveTableEmpty>
      <template v-else>
        <ResponsiveTableRow v-for="(row, rowIndex) in chart.data.rows" :key="rowIndex">
          <template v-for="(cell, cellIndex) in row.cells" :key="cellIndex">
            <ResponsiveTableCell
              v-if="isGenericCell(cell)"
              :class="cn(alignments(cell.alignment), textWrap(cell.nowrap))"
              :cols="toColSpan(cell.cols)"
              :cols-sm="toColSpan(cell.cols_sm)"
              :label="cell.label"
            >
              <DashboardValue :value="cell.value" />
            </ResponsiveTableCell>
            <template v-else>
              <ResponsiveTableCell
                v-if="cell.type === 'progress'"
                :class="cn(alignments(cell.alignment), textWrap(cell.nowrap))"
                :cols="toColSpan(cell.cols)"
                :cols-sm="toColSpan(cell.cols_sm)"
                :label="cell.label"
              >
                <div class="flex items-center">
                  <Progress :model-value="Number(cell.value) || 0" />
                  <span class="ml-2 min-w-16 text-right">{{ Number(cell.value).toFixed(2) }}%</span>
                </div>
              </ResponsiveTableCell>
              <ResponsiveTableCell
                v-else-if="cell.type === 'percentage'"
                :class="cn(alignments(cell.alignment), textWrap(cell.nowrap))"
                :cols="toColSpan(cell.cols)"
                :cols-sm="toColSpan(cell.cols_sm)"
                :label="cell.label"
              >
                <span>{{ (Number(cell.value) * 100).toFixed(2) }}%</span>
              </ResponsiveTableCell>
              <ResponsiveTableCell
                v-else
                :class="cn(alignments(cell.alignment), textWrap(cell.nowrap))"
                :cols="toColSpan(cell.cols)"
                :cols-sm="toColSpan(cell.cols_sm)"
                :label="cell.label"
              >
                {{ cell.value }}
              </ResponsiveTableCell>
            </template>
          </template>
        </ResponsiveTableRow>
      </template>
    </ResponsiveTableBody>
    <ResponsiveTableHeader v-if="chart.data?.footer" class="sticky bottom-0 z-10">
      <template v-for="(cell, cellIndex) in chart.data?.footer.cells" :key="cellIndex">
        <ResponsiveTableCell
          v-if="isGenericCell(cell)"
          :class="cn(alignments(cell.alignment), textWrap(cell.nowrap))"
          :cols="toColSpan(cell.cols)"
          :cols-sm="toColSpan(cell.cols_sm)"
          :label="cell.label"
        >
          <DashboardValue :value="cell.value" />
        </ResponsiveTableCell>
        <template v-else>
          <ResponsiveTableCell
            v-if="cell.type === 'progress'"
            :class="cn(alignments(cell.alignment), textWrap(cell.nowrap))"
            :cols="toColSpan(cell.cols)"
            :cols-sm="toColSpan(cell.cols_sm)"
            :label="cell.label"
          >
            <div class="flex items-center">
              <Progress :model-value="Number(cell.value) || 0" />
              <span class="ml-2 min-w-16 text-right">{{ Number(cell.value).toFixed(2) }}%</span>
            </div>
          </ResponsiveTableCell>
          <ResponsiveTableCell
            v-else-if="cell.type === 'percentage'"
            :class="cn(alignments(cell.alignment), textWrap(cell.nowrap))"
            :cols="toColSpan(cell.cols)"
            :cols-sm="toColSpan(cell.cols_sm)"
            :label="cell.label"
          >
            <span>{{ (Number(cell.value) * 100).toFixed(2) }}%</span>
          </ResponsiveTableCell>
          <ResponsiveTableCell
            v-else
            :class="cn(alignments(cell.alignment), textWrap(cell.nowrap))"
            :cols="toColSpan(cell.cols)"
            :cols-sm="toColSpan(cell.cols_sm)"
            :label="cell.label"
          >
            {{ cell.value }}
          </ResponsiveTableCell>
        </template>
      </template>
    </ResponsiveTableHeader>
  </ResponsiveTable>
  <span class="text-sm text-muted-foreground px-4 mt-2 block"
    >{{ chart.data?.rows?.length || 0 }} {{ chart.data?.rows?.length === 1 ? 'record' : 'records' }}</span
  >
</template>

<script setup lang="ts">
import type { DashboardTable, TableHeaderCell, TableCell, GenericTableCell } from '~/client';
import { cn } from '@/lib/utils';

interface Props {
  chart: DashboardTable;
}

defineProps<Props>();

const isGenericCell = (cell: TableCell | GenericTableCell): cell is GenericTableCell =>
  typeof cell.value === 'object' && cell.value !== null;

const alignments = (align: TableHeaderCell['alignment']) => {
  return {
    'text-left': align === 'left',
    'md:text-center': align === 'center',
    'md:text-right': align === 'right',
  };
};

const textWrap = (nowrap: boolean | undefined) => {
  return {
    'text-wrap': !nowrap,
    'text-nowrap': nowrap,
  };
};

type ColSpan = 1 | 2 | 3 | 4;
const toColSpan = (n: number): ColSpan => (n === 1 || n === 2 || n === 3 || n === 4 ? n : 4);
</script>
