<template>
  <HexagonMapChart
    v-model:map-bounds="mapBounds"
    v-model:zoom="zoom"
    :data="data"
    :refetch="refetch"
    :init-view="initView"
  />
</template>

<script setup lang="ts">
import type { MapView } from '~/client';
import { getQuestionDashboardMap } from '~/client';
import type { BoundsCorners } from '~/types/dashboards/mapTypes';

interface Props {
  initView: MapView;
  questionHash: string;
  projectId: string;
  dateRange: { startDate: string; endDate: string };
  canvassersIds?: string[] | null;
  regions?: string[] | null;
  timezone?: string | null;
}

const props = withDefaults(defineProps<Props>(), { canvassersIds: () => [], regions: () => [], timezone: undefined });

const zoom = ref<number>(5);
const mapBounds = ref<BoundsCorners | null>(null);

const { data, refetch } = useQuery({
  key: () => [
    'projects.id.dashboard.map',
    props.projectId,
    props.questionHash,
    props.dateRange.startDate,
    props.dateRange.endDate,
    props.canvassersIds,
    props.regions,
  ],
  query: () =>
    getQuestionDashboardMap({
      composable: '$fetch',
      path: { project_id: props.projectId, question_hash: props.questionHash },
      body: {
        from_date: props.dateRange.startDate,
        to_date: props.dateRange.endDate,
        canvasser_ids: props.canvassersIds && props.canvassersIds.length ? props.canvassersIds : undefined,
        scale: zoom.value,
        regions: props.regions && props.regions.length ? props.regions : undefined,
        ...(props.timezone ? { timezone: props.timezone } : {}),
        ...(mapBounds.value
          ? {
              left_top_corner: mapBounds.value.top_left,
              right_bottom_corner: mapBounds.value.bottom_right,
            }
          : {}),
      } as any,
    }),
  enabled: () => !!mapBounds.value,
});
</script>
